import numpy as np
import time


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.85

    # Try a family of smooth-ish profiles and pick the best by exact C.
    # A Gaussian-like bump on the step grid gives C well below the constant function.
    best_h = None
    best_c = np.inf

    def consider(h):
        nonlocal best_h, best_c
        h = np.asarray(h, dtype=float)
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return
        c = C_of(h)
        if c < best_c:
            best_c = c
            best_h = h.copy()

    if start is not None:
        consider(start)

    Ns = [50, 100, 200, 400, 800, 1600, 3000, 6000, 12000, 20000, 30000]
    # Gaussian shape: h(x) ~ exp(-(x/sigma)^2). Autoconvolution of Gaussian is Gaussian;
    # minimizing peak over integral favors a broad flat-ish bump. Empirically sigma ~ 0.15-0.25.
    for N in Ns:
        if time.process_time() - t0 > budget:
            break
        x = (np.arange(N) + 0.5) / N - 0.5  # in [-0.5, 0.5) scaled; support width 1 maps to [-1/4,1/4]
        # step width is 1/(2N) in real units; use normalized coordinate u in [-1,1]
        u = (np.arange(N) + 0.5) / N * 2.0 - 1.0
        for sigma in [0.15, 0.2, 0.25, 0.3, 0.35, 0.4, 0.5, 0.6, 0.8]:
            if time.process_time() - t0 > budget:
                break
            h = np.exp(-(u / sigma) ** 2)
            consider(h)

    # Local refinement: coordinate ascent on a moderate N.
    if best_h is not None and time.process_time() - t0 < budget:
        N = min(len(best_h), 2000)
        u = (np.arange(N) + 0.5) / N * 2.0 - 1.0
        h = np.exp(-(u / 0.35) ** 2)
        h = h / h.sum()
        cur = C_of(h)
        step = 0.05
        rng = np.random.default_rng(12345)
        while time.process_time() - t0 < budget and step > 1e-4:
            improved = False
            for _ in range(max(1, N // 20)):
                if time.process_time() - t0 > budget:
                    break
                i = int(rng.integers(0, N))
                for delta in (step, -step):
                    h2 = h.copy()
                    h2[i] = max(0.0, h2[i] + delta)
                    c2 = C_of(h2)
                    if c2 < cur:
                        h, cur = h2, c2
                        improved = True
                        break
            if not improved:
                step *= 0.5
        consider(h)

    if best_h is None:
        return np.ones(50)
    return best_h

