        cand = _upsample(best, target_N)
        if _C(cand) > best_C * 1.02:
            continue
        N = target_N
        scale = max(np.convolve(cand, cand).max(), 1e-12)
        x = np.log(np.maximum(cand, 1e-12))
        local_deadline = min(deadline - 1.0, time.process_time() + budget_seconds * 0.40)
