            if c < best_C:
                best, best_C = h, c
                print("upsample N=%d tau=%.3g C=%.6f" % (N, tau, best_C))
        break

    # Fine-tune on the current best grid.
    if time.process_time() < deadline - 2.0:
        N = len(best)
        scale = max(np.convolve(best, best).max(), 1e-12)
        x = np.log(np.maximum(best, 1e-12))
        for frac in (0.0003, 0.0001, 0.00003, 0.00001):
