    return best

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _upsample(h, N):
    return np.maximum(np.interp(np.linspace(0, 1, N), np.linspace(0, 1, len(h)), h), 0.0)


def _smooth_obj(x, N, tau):
    h = np.exp(np.clip(x, -30, 30))
    S = h.sum()
    if S <= 0:
        return 1e30, np.zeros_like(x)
    conv = np.convolve(h, h)
    m = conv.max()
    z = (conv - m) / tau
    ez = np.exp(z)
    Z = ez.sum()
    Ms = m + tau * np.log(Z)
    p = ez / Z
    gM = 2.0 * np.correlate(p, h, 'full')[N - 1:2 * N - 1]
    F = 2.0 * N * Ms / (S * S)
    dF_dh = (2.0 * N / (S * S)) * gM - (4.0 * N * Ms / (S ** 3)) * h
    return F, dF_dh * h


def _lbfgs_stage(x, N, tau, maxiter, deadline):
    def fun(xv):
        return _smooth_obj(xv, N, tau)
    try:
        res = minimize(fun, x, jac=True, method='L-BFGS-B',
                       bounds=[(-30, 30)] * N,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-15, 'gtol': 1e-12})
        return res.x
    except Exception:
        return x


def _coord_polish(best, best_C, deadline, rng):
    N = len(best)
    step = 0.03
    order = rng.permutation(N)
    pos = 0
    while time.process_time() < deadline:
        improved = False
        chunk = min(300, N)
        idxs = order[pos:pos + chunk]
        if len(idxs) < chunk:
            idxs = np.concatenate([idxs, order[:chunk - len(idxs)]])
        pos = (pos + chunk) % N
        for i in idxs:
            if time.process_time() > deadline:
                break
            base = best[i] if best[i] > 0 else 1e-6
            for factor in (1.0 + step, 1.0 / (1.0 + step)):
                cand = best.copy()
                cand[i] = base * factor
                c = _C(cand)
                if c < best_C - 1e-15:
                    best, best_C = cand, c
                    improved = True
                    break
        if not improved:
            step *= 0.55
            if step < 1e-8:
                cand = np.maximum(best * (1.0 + 0.003 * rng.standard_normal(N)), 0.0)
                c = _C(cand)
                if c < best_C:
                    best, best_C = cand, c
                step = 0.03
                order = rng.permutation(N)
                pos = 0
    return best, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if best.sum() <= 0:
            best = np.ones(200)
    else:
        best = np.ones(200)
    best_C = _C(best)
    print("start C = %.6f, N = %d" % (best_C, len(best)))

    rng = np.random.default_rng(1234)

    # Build a pyramid: refine at progressively larger N, warm-starting each
    # level from the previous. Finer grid + multi-resolution warm start.
    levels = [len(best)]
    for n in (2048, 4096, 8192, 16384):
        if n > levels[-1] and n <= 30000:
            levels.append(n)

    # Main multi-resolution smooth-max loop
    for li, N in enumerate(levels):
        if time.process_time() > deadline - 2.0:
            break
        if N > len(best):
            cand = _upsample(best, N)
        elif N < len(best):
            cand = _upsample(best, N)
        else:
            cand = best.copy()
        c = _C(cand)
        if c > best_C * 1.05 and N > len(best):
            # badly worse; still try but keep best
            pass
        x = np.log(np.maximum(cand, 1e-12))
        scale = max(np.convolve(cand, cand).max(), 1e-12)
        # allocate remaining time over remaining levels
        remaining_levels = len(levels) - li
        level_budget = (deadline - time.process_time()) / max(remaining_levels, 1)
        local_deadline = min(deadline - 1.0, time.process_time() + level_budget * 0.9)
        for frac in (0.01, 0.003, 0.001, 0.0003, 0.0001, 0.00003):
            if time.process_time() > local_deadline:
                break
            tau = frac * scale
            x = _lbfgs_stage(x, N, tau, 100, local_deadline)
            h = np.exp(np.clip(x, -30, 30))
            c2 = _C(h)
            if c2 < best_C:
                best, best_C = h, c2
                print("N=%d tau=%.3g C=%.6f" % (N, tau, best_C))
        # also take best-so-far at this N even if not improved, for warm start
        h = np.exp(np.clip(x, -30, 30))
        c2 = _C(h)
        if c2 < best_C * 1.002:
            best = h
            if c2 < best_C:
                best_C = c2

    # --- Experiment: extra low-tau smooth stages at native N ---
    N = len(best)
    if time.process_time() < deadline - 1.0:
        cand = best.copy()
        x = np.log(np.maximum(cand, 1e-12))
        scale = max(np.convolve(cand, cand).max(), 1e-12)
        for frac in (1e-4, 3e-5, 1e-5):
            if time.process_time() > deadline - 0.5:
                break
            tau = frac * scale
            x = _lbfgs_stage(x, N, tau, 150, deadline - 0.5)
            h = np.exp(np.clip(x, -30, 30))
            c2 = _C(h)
            if c2 < best_C:
                best, best_C = h, c2
                print("lowtau N=%d tau=%.3g C=%.6f" % (N, tau, best_C))

    # Coordinate polish
    if time.process_time() < deadline:
        best, best_C = _coord_polish(best, best_C, deadline, rng)
        print("after polish C = %.6f, N = %d" % (best_C, len(best)))

    print("final C = %.6f, N = %d" % (best_C, len(best)))
    return best

