def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    n = len(h)
    L = 1
    while L < 2 * n - 1:
        L *= 2
    f = np.fft.rfft(h, L)
    conv = np.fft.irfft(f * f, L)[:2 * n - 1]
    return 2.0 * n * np.max(conv) / (s * s)


